import{at as e,it as t,n,vt as r}from"./chunks/framework.B6nQ8gjX.js";var i=JSON.parse(`{"title":"검색 기록","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. 검색 기록 (Search History)","slug":"_1-검색-기록-search-history","link":"#_1-검색-기록-search-history","children":[]},{"level":2,"title":"2. 키워드 기록 (Keyword History)","slug":"_2-키워드-기록-keyword-history","link":"#_2-키워드-기록-keyword-history","children":[]},{"level":2,"title":"3. 검색어 연결 (Query Associations)","slug":"_3-검색어-연결-query-associations","link":"#_3-검색어-연결-query-associations","children":[]}],"relativePath":"ko-KR/user-guide/settings/history.md","filePath":"ko-KR/user-guide/settings/history.md","lastUpdated":1795268921000}`),a={name:`ko-KR/user-guide/settings/history.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="검색-기록" tabindex="-1">검색 기록 <a class="header-anchor" href="#검색-기록" aria-label="Permalink to “검색 기록”">​</a></h1><p>세 탭에서 연 항목, 검색어, 검색어 연결을 각각 관리합니다.</p><h2 id="_1-검색-기록-search-history" tabindex="-1">1. 검색 기록 (Search History) <a class="header-anchor" href="#_1-검색-기록-search-history" aria-label="Permalink to “1. 검색 기록 (Search History)”">​</a></h2><p>검색 결과에서 연 파일, 폴더, 앱의 횟수와 시간을 기록합니다.</p><ul><li><strong>순위 반영</strong>: 열 때마다 1점씩 더하며 최대 10점입니다. 점수는 90일마다 절반으로 줄어듭니다. 유효 점수가 3이면 H3, 5이면 H5 대상이 됩니다. 빠른 검색은 H5 최대 3개와 H3 10개, 인라인 검색은 1개와 3개를 배정합니다. 전체 창은 개수 제한이 없습니다.</li><li><strong>순위 상승 범위</strong>: 유효 일치 등급과 우선순위가 같은 결과 안에서 사용 기록을 비교합니다. 빠른 검색의 유형 설정은 파일·폴더의 전체 이름 일치 등급에도 영향을 줍니다. <a href="./../search-syntax.html">검색 문법</a>을 참고하세요.</li><li><strong>인라인 그룹</strong>: 현재 폴더와 전체 결과를 나누어 표시합니다. 존재하지 않는 경로는 건너뜁니다.</li><li><strong>관리</strong>: 키워드 필터, 개별 삭제, 사용 횟수 N 이하 삭제, 전체 삭제를 지원합니다. 다른 창에서 항목을 열면 목록도 갱신됩니다. 기록을 끄면 새 항목은 추가하지 않지만 기존 항목의 횟수와 시간은 갱신합니다.</li></ul><h2 id="_2-키워드-기록-keyword-history" tabindex="-1">2. 키워드 기록 (Keyword History) <a class="header-anchor" href="#_2-키워드-기록-keyword-history" aria-label="Permalink to “2. 키워드 기록 (Keyword History)”">​</a></h2><p>결과나 작업을 실행하거나 전체 창을 열 때의 원래 검색어를 저장합니다. 입력한 뒤 빠른 검색을 닫기만 하면 기록하지 않습니다.</p><ul><li><strong>Alt+Up / Alt+Down</strong>으로 이전 검색어를 찾고 <strong>Ctrl+Delete</strong>로 현재 항목을 삭제합니다.</li><li>필터, 개별 삭제, 전체 삭제, 횟수별 삭제를 지원합니다. 별도의 기록 스위치를 끄면 새 검색어는 추가하지 않고 기존 검색어의 횟수만 갱신합니다.</li></ul><h2 id="_3-검색어-연결-query-associations" tabindex="-1">3. 검색어 연결 (Query Associations) <a class="header-anchor" href="#_3-검색어-연결-query-associations" aria-label="Permalink to “3. 검색어 연결 (Query Associations)”">​</a></h2><p><strong>검색어 → 대상 경로</strong> 연결을 일반 사용 점수와 별도로 저장합니다.</p><ul><li>같은 정규화 검색어의 일반 검색 결과에서 대상을 <strong>3번 이상</strong> 열면 연결을 통해 결과를 보충할 수 있습니다. 학습된 연결만으로 표시된 항목을 다시 열어도 확인 횟수는 늘지 않습니다.</li><li>검색마다 연결을 최대 <strong>1개</strong> 보충합니다. 낮은 우선순위 대상은 제외하며 연결만으로 찾은 결과는 직접 일치 뒤에 표시합니다.</li><li>연결을 필터링하거나 개별·전체 삭제해도 경로 사용 점수는 유지됩니다.</li></ul>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};